namespace DemaConsulting.CanvasNet.Mermaid.Syntax;

/// <summary>
///     The one-token lookahead of a hand-written diagram parser over a <see cref="SourceScanner"/>, with the error
///     reporting of jison's parsers.
/// </summary>
/// <remarks>
///     <para>
///         Mermaid's parsers are LALR(1) parsers generated by jison: they decide with one token of lookahead, and the lexer
///         state can change while a token is lexed, so lexing must stay in step with parsing. The cursor therefore holds
///         exactly one token (<see cref="Current"/>) and lexes the next one only when it is consumed.
///     </para>
///     <para>
///         When the token is not what the grammar accepts, <see cref="Expect(string[])"/> throws a located
///         <see cref="MermaidSyntaxException"/> whose <see cref="MermaidSyntaxException.Expected"/> lists the accepted
///         tokens, like the "Expecting ..., got ..." of a jison parse error, using the grammar's own descriptions of its
///         token kinds.
///     </para>
///     <para>
///         An instance parses one input on one thread.
///     </para>
/// </remarks>
internal sealed class TokenCursor
{
    /// <summary>The scanner the tokens come from.</summary>
    private readonly SourceScanner _scanner;

    /// <summary>Describes a token kind for messages.</summary>
    private readonly Func<string, string> _describe;

    /// <summary>
    ///     Initializes a cursor and lexes the first token.
    /// </summary>
    /// <param name="scanner">The scanner.</param>
    /// <param name="describe">Describes a token kind for messages (for example <c>NEWLINE</c> as <c>a new line</c>); null quotes the kind.</param>
    /// <exception cref="MermaidSyntaxException">Thrown when the first token cannot be lexed.</exception>
    public TokenCursor(SourceScanner scanner, Func<string, string>? describe = null)
    {
        ArgumentNullException.ThrowIfNull(scanner);
        _scanner = scanner;
        _describe = describe ?? (kind => kind == SourceScanner.EndOfInput ? "the end of the text" : $"'{kind}'");
        Current = scanner.Next();
    }

    /// <summary>
    ///     Gets the lookahead token.
    /// </summary>
    public ScanToken Current { get; private set; }

    /// <summary>
    ///     Gets the scanner, for parsers that inspect or change the lexer state.
    /// </summary>
    public SourceScanner Scanner => _scanner;

    /// <summary>
    ///     Gets a value indicating whether the lookahead token is of one of the kinds.
    /// </summary>
    /// <param name="kinds">The kinds.</param>
    /// <returns>Whether it is.</returns>
    public bool Is(params string[] kinds) => Array.IndexOf(kinds, Current.Kind) >= 0;

    /// <summary>
    ///     Consumes the lookahead token and lexes the next one.
    /// </summary>
    /// <returns>The consumed token.</returns>
    /// <exception cref="MermaidSyntaxException">Thrown when the next token cannot be lexed.</exception>
    public ScanToken Advance()
    {
        var token = Current;
        Current = _scanner.Next();
        return token;
    }

    /// <summary>
    ///     Consumes the lookahead token when it is of one of the kinds, and fails otherwise.
    /// </summary>
    /// <param name="kinds">The accepted kinds.</param>
    /// <returns>The consumed token.</returns>
    /// <exception cref="MermaidSyntaxException">Thrown when the token is of another kind (with the accepted kinds as <see cref="MermaidSyntaxException.Expected"/>).</exception>
    public ScanToken Expect(params string[] kinds)
    {
        if (!Is(kinds))
        {
            throw Error(kinds);
        }

        return Advance();
    }

    /// <summary>
    ///     Creates the exception for a lookahead token that the grammar does not accept.
    /// </summary>
    /// <param name="expectedKinds">The kinds the grammar accepts at this point.</param>
    /// <param name="hint">The suggested fix, or null.</param>
    /// <returns>The located exception, ready to throw.</returns>
    public MermaidSyntaxException Error(IReadOnlyList<string> expectedKinds, string? hint = null)
    {
        ArgumentNullException.ThrowIfNull(expectedKinds);
        var expected = expectedKinds.Select(_describe).Distinct(StringComparer.Ordinal).ToList();
        var found = Current.Kind == SourceScanner.EndOfInput ? "the end of the text" : $"{_describe(Current.Kind)} ('{Current.Text}')";
        return new MermaidSyntaxException(
            MermaidDiagnosticCodes.SyntaxError,
            $"expected {JoinAlternatives(expected)}, found {found}",
            _scanner.Locate(Current.Start),
            hint,
            expected);
    }

    /// <summary>
    ///     Joins alternatives for a message: <c>a</c>, <c>a or b</c>, <c>a, b or c</c>.
    /// </summary>
    /// <param name="items">The alternatives.</param>
    /// <returns>The joined text; <c>nothing</c> when there are none.</returns>
    internal static string JoinAlternatives(IReadOnlyList<string> items) => items.Count switch
    {
        0 => "nothing",
        1 => items[0],
        _ => $"{string.Join(", ", items.Take(items.Count - 1))} or {items[^1]}",
    };
}
